-- One-off backfill of empty CRA months from payslips and invoices.
--
-- For each closed CRA month with no entry at all:
-- 1. Leave read from the Silae payslip ("Congés payés pris DDMMYY[-DDMMYY] (n jours)"
--    -> paid_leave, "Absence non rémunérée" -> unpaid_leave). Every line's day count
--    was checked against the working days in its range. Half days are booked as 'am'
--    (payslips do not say which half).
-- 2. When the month's invoice days on a single project equal the open days left
--    (working days inside the employment minus that leave), the remaining days
--    become client_project days on that project. Otherwise only the leave is filled.
-- Rows were computed offline; a month that got any entry since is skipped.
create temp table cra_payslip_fill (employee_id uuid, month date, day date, part text, status text, project_id uuid);

delete from cra_payslip_fill f
where exists (select 1 from public.cra_entries e where e.employee_id = f.employee_id and e.month = f.month);

select distinct employee_id, month from cra_payslip_fill
on conflict do nothing;

select employee_id, month, day, part, status, project_id from cra_payslip_fill;

update public.cra_months m
set version = m.version + 1, updated_at = now()
where exists (select 1 from cra_payslip_fill f where f.employee_id = m.employee_id and f.month = m.month);

drop table cra_payslip_fill;
